import React from 'react';
// --- 1. IMPORT THE NEW ICONS ---
import { FaUserMd, FaFileMedicalAlt, FaPlus } from 'react-icons/fa';

// --- 2. UPDATED DATA FOR THE CLINIC ---
const pricingPlans = [
  {
    icon: <FaUserMd size={30} />,
    title: 'ONE-TIME CONSULTATION',
    subtitle: 'For a focused session',
    price: '1500',
    priceDetails: '/Per Session',
    features: [
      '60-minute detailed consultation',
      'Initial health assessment',
      'Basic diet chart',
      'Email support for 7 days',
    ],
    buttonText: 'BOOK A SESSION',
    featured: false,
  },
  {
    icon: <FaFileMedicalAlt size={30} />,
    title: '3-MONTH PLAN',
    subtitle: 'For consistent progress',
    originalPrice: '12000',
    discount: '25% OFF',
    price: '9000',
    priceDetails: '/3 Months',
    features: [
      'Everything in One-Time Consultation',
      '6 Follow-up sessions (bi-weekly)',
      'Customized weekly diet plans',
      'Lifestyle & habit coaching',
      'WhatsApp & Email support',
    ],
    buttonText: 'CHOOSE 3-MONTH PLAN',
    featured: true,
  },
  {
    icon: <FaPlus size={30} />,
    title: '6-MONTH PLAN',
    subtitle: 'For long-term transformation',
    originalPrice: '24000',
    discount: '35% OFF',
    price: '15600',
    priceDetails: '/6 Months',
    features: [
      'Everything in 3-Month Plan',
      '12 Follow-up sessions (bi-weekly)',
      'Recipe suggestions & modifications',
      'Monthly progress review calls',
      'Priority support',
    ],
    buttonText: 'CHOOSE 6-MONTH PLAN',
    featured: false,
  },
];


// --- Main Pricing Component ---
const Pricing = () => {
  return (
    <section style={styles.pricingSection}>
      <div style={styles.container}>
        {pricingPlans.map((plan, index) => (
          <div key={index} style={{ ...styles.card, ...(plan.featured ? styles.featuredCard : {}) }}>
            <div style={styles.iconContainer}>{plan.icon}</div>
            <h2 style={styles.title}>{plan.title}</h2>
            <p style={styles.subtitle}>{plan.subtitle}</p>

            <div style={styles.priceContainer}>
              {plan.originalPrice && (
                <span style={styles.originalPrice}>₹{plan.originalPrice}</span>
              )}
              {plan.discount && (
                <span style={styles.discountBadge}>{plan.discount}</span>
              )}
            </div>

            <p style={styles.price}>
              <span style={styles.currency}>₹</span>
              {plan.price}
              <span style={styles.priceDetails}>{plan.priceDetails}</span>
            </p>

            <h3 style={styles.whatsIncluded}>WHAT'S INCLUDED:</h3>
            <ul style={styles.featuresList}>
              {plan.features.map((feature, i) => (
                <li key={i} style={styles.featureItem}>
                  <span style={styles.checkmark}>✓</span> {feature}
                </li>
              ))}
            </ul>

            <button style={{...styles.button, ...(plan.featured ? styles.featuredButton : {})}}>{plan.buttonText} →</button>
          </div>
        ))}
      </div>
    </section>
  );
};


// --- 3. UPDATED STYLES WITH NEW COLOR SCHEME ---
const styles = {
    pricingSection: {
      backgroundColor: '#1a202c', // Dark blue background from header
      padding: '64px 24px',
      fontFamily: 'sans-serif',
      color: '#e2e8f0', // Light text color
    },
    container: {
      maxWidth: '1200px',
      margin: '0 auto',
      display: 'flex',
      justifyContent: 'center',
      gap: '32px',
      flexWrap: 'wrap',
    },
    card: {
      backgroundColor: '#2d3748', // Slightly lighter card background
      padding: '40px',
      borderRadius: '20px',
      border: '1px solid #4a5568', // Subtle border
      width: '350px',
      display: 'flex',
      flexDirection: 'column',
      textAlign: 'left',
      transition: 'transform 0.3s ease, box-shadow 0.3s ease',
    },
    featuredCard: {
      border: '1px solid #a7ffeb', // Mint-teal border for featured plan
      boxShadow: '0 0 25px rgba(167, 255, 235, 0.2)', // Soft glow
      transform: 'scale(1.03)', // Make it slightly larger
    },
    iconContainer: {
      backgroundColor: '#4a5568', // Icon background
      width: '60px',
      height: '60px',
      borderRadius: '12px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      marginBottom: '24px',
      color: '#a7ffeb', // Mint-teal icon color
    },
    title: {
      fontSize: '1.5rem',
      fontWeight: 'bold',
      margin: 0,
      color: '#ffffff', // White title for emphasis
    },
    subtitle: {
      color: '#a0aec0', // Lighter gray for subtitle
      marginBottom: '24px',
    },
    priceContainer: {
        display: 'flex',
        alignItems: 'center',
        gap: '10px',
        height: '24px',
    },
    originalPrice: {
        fontSize: '1.2rem',
        color: '#a0aec0',
        textDecoration: 'line-through',
    },
    discountBadge: {
        backgroundColor: '#28a745',
        color: '#ffffff',
        padding: '4px 8px',
        borderRadius: '6px',
        fontSize: '0.8rem',
        fontWeight: 'bold',
    },
    price: {
      fontSize: '4rem',
      fontWeight: 'bold',
      margin: '8px 0',
      color: '#ffffff',
    },
    currency: {
        fontSize: '2rem',
        color: '#a0aec0',
        marginRight: '8px',
    },
    priceDetails: {
      fontSize: '1rem',
      fontWeight: 'normal',
      color: '#a0aec0',
    },
    whatsIncluded: {
      color: '#a7ffeb', // Mint-teal for "What's Included"
      fontSize: '0.9rem',
      fontWeight: 'bold',
      margin: '24px 0 16px 0',
      letterSpacing: '1px',
    },
    featuresList: {
      listStyle: 'none',
      padding: 0,
      margin: 0,
      flexGrow: 1, // Ensures footer buttons align
    },
    featureItem: {
      marginBottom: '12px',
      display: 'flex',
      alignItems: 'center',
      color: '#e2e8f0', // Light color for features
    },
    checkmark: {
        color: '#a7ffeb', // Mint-teal checkmark
        marginRight: '12px',
        fontWeight: 'bold',
    },
    button: {
      backgroundColor: 'transparent',
      color: '#a7ffeb',
      border: '2px solid #a7ffeb',
      borderRadius: '12px',
      padding: '16px',
      fontSize: '1rem',
      fontWeight: 'bold',
      cursor: 'pointer',
      marginTop: '32px',
      transition: 'background-color 0.3s ease, color 0.3s ease',
    },
    featuredButton: {
      backgroundColor: '#a7ffeb',
      color: '#1a202c', // Dark text on the featured button
    }
};

export default Pricing;
